<?php $title='Tugas & Praktikum';$page='tasks';$pdo=Database::connection();$uid=current_user()['id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$q=$pdo->prepare('SELECT id FROM modules WHERE id=? AND teacher_id=?');$q->execute([(int)$_POST['module_id'],$uid]);if(!$q->fetch())exit('Modul tidak valid');$deadline=$_POST['deadline']?:null;$ins=$pdo->prepare('INSERT INTO tasks(module_id,title,description,deadline,max_score) VALUES(?,?,?,?,?)');$ins->execute([(int)$_POST['module_id'],trim($_POST['title']),trim($_POST['description']),$deadline,(float)$_POST['max_score']]);flash('success','Tugas berhasil dibuat.');redirect('tasks');}$q=$pdo->prepare('SELECT * FROM modules WHERE teacher_id=?');$q->execute([$uid]);$mods=$q->fetchAll();$q=$pdo->prepare('SELECT t.*,m.title module_title,(SELECT COUNT(*) FROM submissions s WHERE s.task_id=t.id) total_submit FROM tasks t JOIN modules m ON m.id=t.module_id WHERE m.teacher_id=? ORDER BY t.created_at DESC');$q->execute([$uid]);$rows=$q->fetchAll();require __DIR__.'/../_dashboard_start.php'; ?>
<div class="page-heading"><div><h1>Tugas & Praktikum</h1><p>Buat tugas untuk siswa pada modul yang Anda kelola.</p></div></div><section class="panel"><h3>Buat Tugas Baru</h3><form method="post" class="form-grid"><?= csrf_field() ?><label>Modul<select name="module_id" required><?php foreach($mods as $m): ?><option value="<?= $m['id'] ?>"><?= e($m['title']) ?></option><?php endforeach; ?></select></label><label>Judul Tugas<input name="title" required></label><label>Deadline<input type="datetime-local" name="deadline"></label><label>Nilai Maksimal<input type="number" name="max_score" min="1" max="100" value="100"></label><label class="full">Instruksi<textarea name="description" rows="4"></textarea></label><button class="btn btn-primary">Publikasikan Tugas</button></form></section><section class="panel"><h3>Daftar Tugas</h3><div class="table-wrap"><table><thead><tr><th>Tugas</th><th>Modul</th><th>Deadline</th><th>Pengumpulan</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= e($r['module_title']) ?></td><td><?= e($r['deadline']??'—') ?></td><td><?= e($r['total_submit']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php require __DIR__.'/../_dashboard_end.php'; ?>